def centroid(cells):
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    return sum(rs)/len(rs), sum(cs)/len(cs)

def f(g):
    bg=g[0][0]; H,W=len(g),len(g[0]); out=[row[:] for row in g]; seen=set()
    objs=[]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v==bg or (r,c) in seen: continue
            stack=[(r,c)]; comp=[]
            while stack:
                x,y=stack.pop()
                if (x,y) in seen: continue
                seen.add((x,y)); comp.append((x,y))
                for dx,dy in ((1,1),(1,-1),(-1,1),(-1,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<H and 0<=ny<W and g[nx][ny]==v and (nx,ny) not in seen:
                        stack.append((nx,ny))
            if len(comp)<2: continue
            objs.append((comp,v))
    if not objs: return out
    allc=[p for o,_ in objs for p in o]
    cr,cc=centroid(allc)
    for comp,v in objs:
        oc,ocx=centroid(comp)
        dr=(1 if oc>cr else -1) if abs(oc-cr)>0.01 else 0
        dc=(1 if ocx>cc else -1) if abs(ocx-cc)>0.01 else 0
        if dr==0 and dc==0: continue
        cur=tuple(sorted(comp)[-1]) if (dr+dc)>0 else tuple(sorted(comp)[0])
        # pick end furthest along direction
        ends={tuple(sorted(comp))[0],tuple(sorted(comp))[-1]}
        best=max(ends,key=lambda p:(p[0]*dr+p[1]*dc))
        while True:
            nr,nc=best[0]+dr,best[1]+dc
            if not(0<=nr<H and 0<=nc<W) or g[nr][nc]!=bg: break
            out[nr][nc]=v; best=(nr,nc)
    return out

